/* 手机或电脑切换外观时，聊天页随系统更新。 */
@media (prefers-color-scheme: dark) {
  .chat-detail-screen {
    color-scheme: dark;
    --sb-dark-page: #101012;
    --sb-dark-panel: #222225;
    --sb-dark-ink: #f3f3f4;
    --chat-header-title-color: #fff !important;
    --sb-dark-muted: #b5b5bd;
    --sb-dark-line: #414147;
    --chat-bg: var(--sb-dark-page) !important;
    --sb-fill-me: #3a3a40;
    --sb-fill-them: #252528;
    --bubble-me-color: var(--sb-dark-ink);
    --bubble-them-color: var(--sb-dark-ink);
    --input-area-bg: var(--sb-dark-page);
    --input-box-bg: #29292d;
    --input-caret-color: var(--sb-dark-ink);
    --input-btn-color: #171717;
    --send-btn-color: var(--sb-dark-ink);
    --timestamp-color: var(--sb-dark-muted);
    --date-divider-bg: var(--sb-dark-panel);
    --date-divider-color: var(--sb-dark-muted);
    --reply-detached-name-color: var(--sb-dark-muted);
    --reply-detached-text-color: var(--sb-dark-muted);
    --voice-me-color: var(--sb-dark-ink);
    --voice-them-color: var(--sb-dark-ink);
    --voice-them-bar-active: var(--sb-dark-ink);
    --voice-them-bar-inactive: var(--sb-dark-ink);
    color: #171717;
    background: var(--sb-dark-page) !important;
  }
  .chat-detail-screen .chat-messages-custom {
    color: var(--sb-dark-ink);
    background: var(--sb-dark-page) !important;
  }
  .chat-detail-screen.chat-detail-screen .chat-header-custom::before {
    color: var(--sb-dark-muted);
    background: var(--sb-dark-panel) !important;
  }
  .chat-detail-screen.chat-detail-screen .chat-header-custom::after {
    background:
      var(--sb-banner-art) center 46% / cover no-repeat padding-box,
      linear-gradient(var(--sb-dark-panel), var(--sb-dark-panel)) border-box !important;
  }
  .chat-detail-screen.chat-detail-screen .chat-header-custom .chat-header-title,
  .chat-detail-screen.chat-detail-screen .chat-header-custom .chat-header-title * {
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .chat-detail-screen .chat-header-custom :is(.header-btn-phone, .header-btn-video, .header-btn-info) {
    color: var(--sb-dark-ink) !important;
    background-color: #29292d !important;
  }
  .chat-detail-screen .chat-header-custom :is(.header-btn-phone, .header-btn-video) :is(svg, img) {
    color: var(--sb-dark-ink) !important;
    filter: brightness(0) invert(1) !important;
  }
  .chat-detail-screen .chat-header-custom .header-btn-info {
    background:
      radial-gradient(circle at calc(50% - 4.5px) 50%, var(--sb-dark-ink) 1px, transparent 1.3px),
      radial-gradient(circle at 50% 50%, var(--sb-dark-ink) 1px, transparent 1.3px),
      radial-gradient(circle at calc(50% + 4.5px) 50%, var(--sb-dark-ink) 1px, transparent 1.3px),
      #29292d !important;
  }
  .chat-detail-screen .input-area-custom :is(.input-box-custom, textarea, input[type="text"], [contenteditable="true"]) {
    color: #fff !important;
